import struct
blob = open("lcpu_blob.bin","rb").read()
# search for the patch record/buf addresses as little-endian words in the image
targets = {
  0x204FDF00: "HCPU-view patch record (0x204FDF00)",
  0x000FDF00: "LCPU-view patch record (0x000FDF00)",
  0x204FA000: "HCPU-view patch start (0x204FA000)",
  0x000FA000: "LCPU-view patch start (0x000FA000)",
  0x204EC000: "patch buf (0x204EC000)",
  0x000EC000: "LCPU-view patch buf (0x000EC000)",
}
hits = {}
for i in range(0, len(blob)-3, 2):
    w = struct.unpack_from('<I', blob, i)[0]
    if w in targets:
        hits.setdefault(w, []).append(hex(i))
for w, addrs in hits.items():
    print("word 0x%08X (%s): %d hits: %s" % (w, targets[w], len(addrs), addrs[:8]))
EOF

