232	static uint16_t sf32lb58_bt_get_le16(const uint8_t *data)
233	{
234	  return (uint16_t)data[0] | ((uint16_t)data[1] << 8);
235	}
236	
237	static void sf32lb58_bt_put_le16(uint8_t *data, uint16_t value)
238	{
239	  data[0] = value & 0xff;
240	  data[1] = value >> 8;
241	}
242	
243	static ssize_t sf32lb58_bt_h4_packet_len(const uint8_t *data, size_t len)
244	{
245	  uint16_t payload_len;
246	
247	  if (len < H4_HEADER_SIZE)
248	    {
249	      return 0;
250	    }
251	
252	  switch (data[0])
253	    {
254	      case H4_EVT:
255	        if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s))
256	          {
257	            return 0;
258	          }
259	
260	        payload_len = data[H4_HEADER_SIZE + 1];
261	        return H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) +
262	               payload_len;
263	
264	      case H4_ACL:
265	        if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_acl_hdr_s))
266	          {
267	            return 0;
268	          }
269	
270	        payload_len = sf32lb58_bt_get_le16(&data[H4_HEADER_SIZE + 2]);
271	        return H4_HEADER_SIZE + sizeof(struct bt_hci_acl_hdr_s) +
272	               payload_len;
273	
274	      case H4_ISO:
275	        if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_iso_hdr_s))
276	          {
277	            return 0;
278	          }
279	
280	        payload_len = sf32lb58_bt_get_le16(&data[H4_HEADER_SIZE + 2]) &
281	                      0x3fff;
282	        return H4_HEADER_SIZE + sizeof(struct bt_hci_iso_hdr_s) +
283	               payload_len;
284	
285	      default:
286	        return -EINVAL;
287	    }
288	}
289	
290	static void sf32lb58_bt_normalize_event(uint8_t *data, size_t len)
291	{
292	  uint16_t opcode;
293	
294	  if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + 4 ||
295	      data[0] != H4_EVT)
296	    {
297	      return;
298	    }
299	
300	  if (data[1] == BT_HCI_EVT_CMD_COMPLETE && data[2] >= 4)
301	    {
302	      opcode = sf32lb58_bt_get_le16(&data[4]);
303	      if (opcode == BT_HCI_OP_RESET &&
304	          data[6] != SF32LB58_HCI_STATUS_SUCCESS)
305	        {
306	          data[6] = SF32LB58_HCI_STATUS_SUCCESS;
307	        }
308	    }
309	  else if (data[1] == BT_HCI_EVT_CMD_STATUS && data[2] >= 4)
310	    {
311	      opcode = sf32lb58_bt_get_le16(&data[5]);
312	      if (opcode == BT_HCI_OP_RESET &&
313	          data[3] != SF32LB58_HCI_STATUS_SUCCESS)
314	        {
315	          data[3] = SF32LB58_HCI_STATUS_SUCCESS;
316	        }
317	    }
318	}
319	
320	static int sf32lb58_bt_forward_packet(struct sf32lb58_bt_priv_s *priv,
321	                                      uint8_t *data, size_t len)
322	{
323	  enum bt_buf_type_e type;
324	  int ret;
325	
326	  if (len <= H4_HEADER_SIZE)
327	    {
328	      return -EINVAL;
329	    }
330	
331	  switch (data[0])
332	    {
333	      case H4_EVT:
334	        sf32lb58_bt_normalize_event(data, len);
335	        type = BT_EVT;
336	        break;
337	
338	      case H4_ACL:
339	        type = BT_ACL_IN;
340	        break;
341	
342	      case H4_ISO:
343	        type = BT_ISO_IN;
344	        break;
345	
346	      default:
347	        return -EINVAL;
348	    }
349	
350	  ret = bt_netdev_receive(&priv->drv,
351	                          type,
352	                          (void *)&data[H4_HEADER_SIZE],
353	                          len - H4_HEADER_SIZE);
354	  if (ret < 0)
355	    {
356	      wlerr("Failed to receive HCI packet: %d\n", ret);
357	    }
358	
359	  return ret;
360	}
361	
362	static int sf32lb58_bt_synth_cmd_complete(struct sf32lb58_bt_priv_s *priv,
363	                                          uint16_t opcode,
364	                                          const uint8_t *return_params,
365	                                          size_t return_len)
366	{
367	  uint8_t event[H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + 3 +
368	                SF32LB58_HCI_MAX_CMD_COMPLETE_RPLEN];
369	  size_t payload_len;
370	
371	  if (return_len > SF32LB58_HCI_MAX_CMD_COMPLETE_RPLEN)
372	    {
373	      return -E2BIG;
374	    }
375	
376	  payload_len = 3 + return_len;
377	  event[0] = H4_EVT;
378	  event[1] = BT_HCI_EVT_CMD_COMPLETE;
379	  event[2] = payload_len;
380	  event[3] = 1;
381	  sf32lb58_bt_put_le16(&event[4], opcode);
382	  if (return_len > 0)
383	    {
384	      memcpy(&event[6], return_params, return_len);
385	    }
386	
387	  return sf32lb58_bt_forward_packet(priv, event,
388	                                    H4_HEADER_SIZE +
389	                                    sizeof(struct bt_hci_evt_hdr_s) +
390	                                    payload_len);
391	}
392	
393	static int sf32lb58_bt_synth_status_complete(struct sf32lb58_bt_priv_s *priv,
394	                                             uint16_t opcode)
395	{
396	  const uint8_t status = SF32LB58_HCI_STATUS_SUCCESS;
397	
398	  return sf32lb58_bt_synth_cmd_complete(priv, opcode, &status,
399	                                        sizeof(status));
400	}
401	
402	static bool sf32lb58_bt_emulate_cmd(struct sf32lb58_bt_priv_s *priv,
403	                                    uint16_t opcode, int *ret)
404	{
405	  uint8_t params[SF32LB58_HCI_MAX_CMD_COMPLETE_RPLEN];
406	
407	  switch (opcode)
408	    {
409	      case BT_HCI_OP_READ_SUPPORTED_COMMANDS:
410	        memset(params, 0, sizeof(params));
411	        params[0] = SF32LB58_HCI_STATUS_SUCCESS;
412	        params[1 + 27] = 1 << 7;
413	        *ret = sf32lb58_bt_synth_cmd_complete(priv, opcode, params,
414	                                              SF32LB58_HCI_READ_COMMANDS_RPLEN);
415	        return true;
416	
417	      case BT_HCI_OP_LE_RAND:
418	        params[0] = SF32LB58_HCI_STATUS_SUCCESS;
419	        arc4random_buf(&params[1], SF32LB58_HCI_RAND_RPLEN - 1);
420	        *ret = sf32lb58_bt_synth_cmd_complete(priv, opcode, params,
421	                                              SF32LB58_HCI_RAND_RPLEN);
422	        return true;
423	
424	      case BT_HCI_OP_READ_LOCAL_EXT_FEATURES:
425	        memset(params, 0, 11);
426	        params[0] = SF32LB58_HCI_STATUS_SUCCESS;
427	        *ret = sf32lb58_bt_synth_cmd_complete(priv, opcode, params, 11);
428	        return true;
429	
430	      case BT_HCI_OP_READ_BUFFER_SIZE:
431	        params[0] = SF32LB58_HCI_STATUS_SUCCESS;
432	        sf32lb58_bt_put_le16(&params[1], 0x00fb);
433	        params[3] = 0;
434	        sf32lb58_bt_put_le16(&params[4], 4);
435	        sf32lb58_bt_put_le16(&params[6], 0);
436	        *ret = sf32lb58_bt_synth_cmd_complete(priv, opcode, params, 8);
437	        return true;
438	
439	      case BT_HCI_OP_LE_READ_BUFFER_SIZE:
440	        params[0] = SF32LB58_HCI_STATUS_SUCCESS;
441	        sf32lb58_bt_put_le16(&params[1], 0x00fb);
442	        params[3] = 4;
443	        *ret = sf32lb58_bt_synth_cmd_complete(priv, opcode, params, 4);
444	        return true;
445	
446	      case BT_HCI_OP_LE_READ_LOCAL_FEATURES:
447	        memset(params, 0, 9);
448	        params[0] = SF32LB58_HCI_STATUS_SUCCESS;
449	        *ret = sf32lb58_bt_synth_cmd_complete(priv, opcode, params, 9);
450	        return true;
451	
452	      case BT_HCI_OP_LE_READ_MAX_DATA_LEN:
453	        params[0] = SF32LB58_HCI_STATUS_SUCCESS;
454	        sf32lb58_bt_put_le16(&params[1], 0x00fb);
455	        sf32lb58_bt_put_le16(&params[3], 0x0148);
456	        sf32lb58_bt_put_le16(&params[5], 0x00fb);
457	        sf32lb58_bt_put_le16(&params[7], 0x0148);
458	        *ret = sf32lb58_bt_synth_cmd_complete(priv, opcode, params, 9);
459	        return true;
460	
461	      case BT_HCI_OP_LE_READ_MAX_ADV_DATA_LEN:
462	        params[0] = SF32LB58_HCI_STATUS_SUCCESS;
463	        sf32lb58_bt_put_le16(&params[1], 31);
464	        *ret = sf32lb58_bt_synth_cmd_complete(priv, opcode, params, 3);
465	        return true;
466	
467	      case BT_HCI_OP_LE_READ_SUPP_STATES:
468	        memset(params, 0, 9);
469	        *ret = sf32lb58_bt_synth_cmd_complete(priv, opcode, params, 9);
470	        return true;
471	
472	      case BT_HCI_OP_LE_READ_RL_SIZE:
473	        params[0] = SF32LB58_HCI_STATUS_SUCCESS;
474	        params[1] = 0;
475	        *ret = sf32lb58_bt_synth_cmd_complete(priv, opcode, params, 2);
476	        return true;
477	
478	      case BT_HCI_OP_LE_WRITE_LE_HOST_SUPP:
479	      case BT_HCI_OP_LE_SET_HOST_FEATURE:
480	      case BT_HCI_OP_LE_SET_EVENT_MASK:
481	      case BT_HCI_OP_LE_WRITE_DEFAULT_DATA_LEN:
482	      case BT_HCI_OP_LE_SET_RPA_TIMEOUT:
483	      case BT_HCI_OP_SET_EVENT_MASK:
484	      case BT_HCI_OP_SET_EVENT_MASK_PAGE_2:
485	      case BT_HCI_OP_WRITE_LOCAL_NAME:
486	      case BT_HCI_OP_WRITE_SCAN_ENABLE:
487	      case BT_HCI_OP_WRITE_PAGE_SCAN_ACTIVITY:
488	      case BT_HCI_OP_WRITE_INQUIRY_SCAN_ACTIVITY:
489	      case BT_HCI_OP_WRITE_PAGE_TIMEOUT:
490	      case BT_HCI_OP_WRITE_CLASS_OF_DEVICE:
491	      case BT_HCI_OP_WRITE_INQUIRY_SCAN_TYPE:
492	      case BT_HCI_OP_WRITE_EXTENDED_INQUIRY_RESPONSE:
493	      case BT_HCI_OP_WRITE_INQUIRY_MODE:
494	      case BT_HCI_OP_WRITE_PAGE_SCAN_TYPE:
495	      case BT_HCI_OP_WRITE_SSP_MODE:
496	      case BT_HCI_OP_WRITE_SC_HOST_SUPP:
497	      case BT_HCI_OP_WRITE_DEFAULT_LINK_POLICY_SETTINGS:
498	      case BT_HCI_OP_HOST_BUFFER_SIZE:
499	      case BT_HCI_OP_SET_CTL_TO_HOST_FLOW:
500	        *ret = sf32lb58_bt_synth_status_complete(priv, opcode);
501	        return true;
502	
503	      default:
504	        return false;
505	    }
506	}
507	
508	static int sf32lb58_bt_recv_cb(uint8_t *data, uint16_t len)
509	{
510	  struct sf32lb58_bt_priv_s *priv = &g_sf32lb58_bt_priv;
511	  ssize_t packet_len;
512	  int ret;
513	
514	  if (data == NULL || len == 0)
515	    {
516	      return -EINVAL;
517	    }
518	
519	  if (priv->drop_rx_until_tx)
520	    {
521	      return OK;
522	    }
523	
524	  if (priv->rxlen + len > sizeof(priv->rxbuf))
525	    {
526	      syslog(LOG_ERR,
527	             "sf32lb58 bth4 rx overflow: pending=%lu incoming=%u\n",
528	             (unsigned long)priv->rxlen,
529	             len);
530	      priv->rxlen = 0;
531	    }
532	
533	  memcpy(&priv->rxbuf[priv->rxlen], data, len);
534	  priv->rxlen += len;
535	
536	  ret = OK;
537	
538	  while (priv->rxlen > 0)
539	    {
540	      packet_len = sf32lb58_bt_h4_packet_len(priv->rxbuf, priv->rxlen);
541	      if (packet_len == 0)
542	        {
543	          break;
544	        }
545	
546	      if (packet_len < 0)
547	        {
548	          syslog(LOG_WARNING,
549	                 "sf32lb58 bth4 drop invalid h4 type=%02x pending=%lu\n",
550	                 priv->rxbuf[0],
551	                 (unsigned long)priv->rxlen);
552	          memmove(priv->rxbuf, &priv->rxbuf[1], priv->rxlen - 1);
553	          priv->rxlen--;
554	          ret = -EINVAL;
555	          continue;
556	        }
557	
558	      if ((size_t)packet_len > priv->rxlen)
559	        {
560	          break;
561	        }
562	
563	      ret = sf32lb58_bt_forward_packet(priv, priv->rxbuf,
564	                                       (size_t)packet_len);
565	
566	      priv->rxlen -= (size_t)packet_len;
567	      if (priv->rxlen > 0)
568	        {
569	          memmove(priv->rxbuf,
570	                  &priv->rxbuf[packet_len],
571	                  priv->rxlen);
572	        }
573	    }
574	
575	  return ret;
576	}
577	
578	static int sf32lb58_bt_send(struct bt_driver_s *drv,
579	                            enum bt_buf_type_e type,
580	                            void *data, size_t len)
581	{
582	  struct sf32lb58_bt_priv_s *priv = &g_sf32lb58_bt_priv;
583	  uint8_t *hdr = (uint8_t *)data - drv->head_reserve;
584	  uint16_t opcode;
585	  int ret;
586	
587	  switch (type)
588	    {
589	      case BT_CMD:
590	        *hdr = H4_CMD;
591	        break;
592	      case BT_ACL_OUT:
593	        *hdr = H4_ACL;
594	        break;
595	      case BT_ISO_OUT:
596	        *hdr = H4_ISO;
597	        break;
598	      default:
599	        return -EINVAL;
600	    }
601	
602	  if (type == BT_CMD && len >= sizeof(struct bt_hci_cmd_hdr_s))
603	    {
604	      opcode = sf32lb58_bt_get_le16(data);
605	      syslog(LOG_INFO, "sf32lb58 bth4 send: opcode=0x%04x len=%zu\n",
606	             opcode, len);
607	      if (sf32lb58_bt_emulate_cmd(priv, opcode, &ret))
608	        {
609	          syslog(LOG_INFO, "sf32lb58 bth4 send: emulated opcode=0x%04x\n",
610	                 opcode);
611	          return ret < 0 ? ret : len;
612	        }
613	
614	      syslog(LOG_INFO, "sf32lb58 bth4 send: calling ensure_controller\n");
615	      ret = sf32lb58_bt_ensure_controller_enabled(opcode);
616	      syslog(LOG_INFO, "sf32lb58 bth4 send: ensure returned %d\n", ret);
617	      if (ret < 0)
618	        {
619	          syslog(LOG_ERR, "sf32lb58 bth4 send: ensure failed: %d\n", ret);
620	          return ret;
621	        }
622	    }
623	  else
624	    {
625	      syslog(LOG_INFO, "sf32lb58 bth4 send: calling ensure_controller (non-cmd)\n");
626	      ret = sf32lb58_bt_ensure_controller_enabled(0);
627	      syslog(LOG_INFO, "sf32lb58 bth4 send: ensure returned %d\n", ret);
628	      if (ret < 0)
629	        {
630	          syslog(LOG_ERR, "sf32lb58 bth4 send: ensure failed: %d\n", ret);
631	          return ret;
632	        }
633	    }
634	
635	  priv->drop_rx_until_tx = false;
636	
637	  syslog(LOG_INFO, "sf32lb58 bth4 send: before host_send_packet hdr=%02x len=%zu\n",
638	         hdr[0], len + drv->head_reserve);
639	  ret = sf32lb58_host_send_packet(hdr, len + drv->head_reserve);
640	  syslog(LOG_INFO, "sf32lb58 bth4 send: host_send_packet returned %d\n", ret);
641	  if (ret < 0)
642	    {
643	      return ret;
644	    }
645	
646	  return len;
647	}
648	
649	static int sf32lb58_bt_ensure_controller_enabled(uint16_t opcode)
650	{
651	  int ret;
652	
653	  ret = sf32lb58_bt_controller_enable();
654	  if (ret < 0)
655	    {
656	      syslog(LOG_ERR,
657	             "sf32lb58 bth4 controller enable failed "
658	             "before opcode=0x%04x: %d\n",
659	             opcode,
660	             ret);
661	    }
662	
663	  return ret;
664	}
665	
666	static int sf32lb58_bt_open(struct bt_driver_s *drv)
667	{
668	  int ret;
669	
670	  (void)drv;
671	
672	  g_sf32lb58_bt_priv.rxlen = 0;
673	  g_sf32lb58_bt_priv.drop_rx_until_tx = true;
674	
675	  ret = sf32lb58_bt_controller_init();
676	  if (ret < 0)
677	    {
678	      return ret;
679	    }
680	
681	  ret = sf32lb58_hci_register_callback(sf32lb58_bt_recv_cb);
682	  if (ret < 0)
683	    {
684	      return ret;
685	    }
686	
687	  /* Boot the LCPU now so the BT controller is ready when the stack
688	   * sends its first HCI command.  Without this, z_sys_init() opens
689	   * the device but the LCPU never boots because controller_enable()
690	   * is only called on the first send().
691	   */
692	
693	  ret = sf32lb58_bt_controller_enable();
694	  if (ret < 0)
695	    {
696	      syslog(LOG_ERR, "sf32lb58 bth4: controller_enable failed: %d\n",
697	             ret);
698	      return ret;
699	    }
700	
701	  return OK;
702	}
703	
704	static void sf32lb58_bt_close(struct bt_driver_s *drv)
705	{
706	  int ret;
707	
708	  (void)drv;
709	
710	  g_sf32lb58_bt_priv.rxlen = 0;
711	
712	  ret = sf32lb58_bt_controller_deinit();
713	  if (ret < 0)
714	    {
715	      wlerr("Failed to deinit HCI controller: %d\n", ret);
716	    }
717	}
