722	
723	int sf32lb58_bt_initialize(void)
724	{
725	  int ret;
726	
727	  ret = uart_bth4_register("/dev/ttyHCI0", &g_sf32lb58_bt_priv.drv);
728	  if (ret < 0 && ret != -EEXIST)
729	    {
730	      wlerr("Failed to register /dev/ttyHCI0: %d\n", ret);
731	      return ret;
732	    }
733	
734	  /* Do NOT call z_sys_init() here.  The bluetoothd framework calls
735	   * bt_sal_init() → z_sys_init() during its startup.  Calling it
736	   * twice causes the second call to block or fail.
737	   */
738	
739	  return OK;
740	}
