163	static void sf32lb58_bt_clean_nvds_shared(void)
164	{
165	  up_clean_dcache((uintptr_t)SF32LB58_BT_NVDS_BUF_START,
166	                  (uintptr_t)SF32LB58_BT_NVDS_BUF_START + SF32LB58_BT_NVDS_BUF_SIZE);
167	}
168	
169	static bool sf32lb58_bt_rx_ring_valid(struct circular_buf *rx_ring)
170	{
171	  uint32_t rd_ptr = rx_ring->read_idx_mirror;
172	  uint32_t wr_ptr = rx_ring->write_idx_mirror;
173	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
174	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
175	  long buf_size = rx_ring->buffer_size;
176	
177	  return buf_size == (long)SF32LB58_BT_RING_DATA_SIZE &&
178	         rd_idx <= SF32LB58_BT_RING_DATA_SIZE &&
179	         wr_idx <= SF32LB58_BT_RING_DATA_SIZE;
180	}
181	
182	static bool sf32lb58_bt_rx_ring_ready(const char *tag)
183	{
184	  struct circular_buf *rx_ring =
185	      (struct circular_buf *)SF32LB58_BT_RX_BUF_ADDR;
186	  uint32_t rd_ptr = rx_ring->read_idx_mirror;
187	  uint32_t wr_ptr = rx_ring->write_idx_mirror;
188	  long buf_size = rx_ring->buffer_size;
189	
190	  if (!sf32lb58_bt_rx_ring_valid(rx_ring))
191	    {
192	      syslog(LOG_WARNING,
193	             "%s rx ring invalid: buf=%ld expected=%lu rd=%08lx wr=%08lx\n",
194	             tag,
195	             buf_size,
196	             (unsigned long)SF32LB58_BT_RING_DATA_SIZE,
197	             (unsigned long)rd_ptr,
198	             (unsigned long)wr_ptr);
199	      return false;
200	    }
201	
202	  return true;
203	}
204	
205	static int sf32lb58_bt_wait_rx_ring_ready(void)
206	{
207	  struct circular_buf *rx_ring =
208	      (struct circular_buf *)SF32LB58_BT_RX_BUF_ADDR;
209	  int i;
210	
211	  syslog(LOG_INFO, "sf32lb58 wait_rx_ring: buf=0x%08x size=%lu\n",
212	         (unsigned int)SF32LB58_BT_RX_BUF_ADDR,
213	         (unsigned long)SF32LB58_BT_RX_BUF_SIZE);
214	
215	  for (i = 0; i < 1000; i++)
216	    {
217	      up_invalidate_dcache((uintptr_t)SF32LB58_BT_RX_BUF_ADDR,
218	                           (uintptr_t)SF32LB58_BT_RX_BUF_ADDR +
219	                           SF32LB58_BT_RX_BUF_SIZE);
220	
221	      if (sf32lb58_bt_rx_ring_valid(rx_ring))
222	        {
223	          syslog(LOG_INFO, "sf32lb58 wait_rx_ring: ready after %d iters\n", i);
224	          return OK;
225	        }
226	
227	      if (i < 5 || i % 100 == 0)
228	        {
229	          syslog(LOG_INFO, "sf32lb58 wait_rx_ring: iter=%d "
230	                 "buf_size=%ld rd=%08lx wr=%08lx\n",
231	                 i,
232	                 rx_ring->buffer_size,
233	                 (unsigned long)rx_ring->read_idx_mirror,
234	                 (unsigned long)rx_ring->write_idx_mirror);
235	        }
236	
237	      usleep(1000);
238	    }
239	
240	  sf32lb58_bt_rx_ring_ready("sf32lb58 wait");
241	  return -ETIMEDOUT;
242	}
