274	static size_t sf32lb58_bt_ring_data_len(uint32_t rd_ptr, uint32_t wr_ptr,
275	                                        uint32_t buffer_size)
276	{
277	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
278	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
279	  uint32_t rd_mirror = CB_GET_PTR_MIRROR(rd_ptr);
280	  uint32_t wr_mirror = CB_GET_PTR_MIRROR(wr_ptr);
281	
282	  if (rd_idx == wr_idx)
283	    {
284	      return rd_mirror == wr_mirror ? 0 : buffer_size;
285	    }
286	
287	  if (wr_idx > rd_idx)
288	    {
289	      return wr_idx - rd_idx;
290	    }
291	
292	  return buffer_size - (rd_idx - wr_idx);
293	}
294	
295	static size_t sf32lb58_bt_ring_space_len(uint32_t rd_ptr, uint32_t wr_ptr,
296	                                         uint32_t buffer_size)
297	{
298	  return buffer_size - sf32lb58_bt_ring_data_len(rd_ptr, wr_ptr,
299	                                                  buffer_size);
300	}
301	
302	static uint32_t sf32lb58_bt_ring_advance(uint32_t ptr, size_t len,
303	                                         uint32_t buffer_size)
304	{
305	  uint32_t idx = CB_GET_PTR_IDX(ptr);
306	  uint32_t mirror = CB_GET_PTR_MIRROR(ptr);
307	
308	  idx += len;
309	  if (idx >= buffer_size)
310	    {
311	      idx -= buffer_size;
312	      mirror = ~mirror;
313	    }
314	
315	  return CB_MAKE_PTR_IDX_MIRROR(idx, mirror);
316	}
317	
318	static size_t sf32lb58_bt_ring_copy(uint8_t *dst,
319	                                    const struct circular_buf *rx_ring,
320	                                    uint32_t rd_ptr,
321	                                    size_t len)
322	{
323	  const uint8_t *pool = (const uint8_t *)(rx_ring + 1);
324	  uint32_t rd_idx = CB_GET_PTR_IDX(rd_ptr);
325	  size_t tail;
326	
327	  if (len == 0)
328	    {
329	      return 0;
330	    }
331	
332	  tail = rx_ring->buffer_size - rd_idx;
333	  if (tail >= len)
334	    {
335	      memcpy(dst, &pool[rd_idx], len);
336	      return len;
337	    }
338	
339	  memcpy(dst, &pool[rd_idx], tail);
340	  memcpy(&dst[tail], pool, len - tail);
341	  return len;
342	}
343	
344	static size_t sf32lb58_bt_ring_write(struct circular_buf *tx_ring,
345	                                     const uint8_t *src, size_t len)
346	{
347	  uint8_t *pool = (uint8_t *)(tx_ring + 1);
348	  uint32_t wr_ptr = tx_ring->write_idx_mirror;
349	  uint32_t wr_idx = CB_GET_PTR_IDX(wr_ptr);
350	  size_t space;
351	  size_t tail;
352	
353	  space = sf32lb58_bt_ring_space_len(tx_ring->read_idx_mirror,
354	                                     wr_ptr,
355	                                     tx_ring->buffer_size);
356	  if (space == 0)
357	    {
358	      return 0;
359	    }
360	
361	  if (len > space)
362	    {
363	      len = space;
364	    }
365	
366	  tail = tx_ring->buffer_size - wr_idx;
367	  if (tail >= len)
368	    {
369	      memcpy(&pool[wr_idx], src, len);
370	      up_clean_dcache((uintptr_t)&pool[wr_idx],
371	                      (uintptr_t)&pool[wr_idx] + len);
372	    }
373	  else
374	    {
375	      memcpy(&pool[wr_idx], src, tail);
376	      memcpy(pool, &src[tail], len - tail);
377	      up_clean_dcache((uintptr_t)&pool[wr_idx],
378	                      (uintptr_t)&pool[wr_idx] + tail);
379	      up_clean_dcache((uintptr_t)pool,
380	                      (uintptr_t)pool + len - tail);
381	    }
382	
383	  tx_ring->write_idx_mirror = sf32lb58_bt_ring_advance(wr_ptr, len,
384	                                                       tx_ring->buffer_size);
385	  up_clean_dcache((uintptr_t)tx_ring,
386	                  (uintptr_t)tx_ring + sizeof(*tx_ring));
387	  __DSB();
388	
389	  return len;
390	}
391	
392	static size_t sf32lb58_bt_tx_pending(struct circular_buf *tx_ring,
393	                                     uint32_t *rd_ptr,
394	                                     uint32_t *wr_ptr)
395	{
396	  uint32_t rd;
397	  uint32_t wr;
398	
399	  up_invalidate_dcache((uintptr_t)SF32LB58_BT_TX_BUF_ADDR,
400	                       (uintptr_t)SF32LB58_BT_TX_BUF_ADDR +
401	                       sizeof(*tx_ring));
402	
403	  rd = tx_ring->read_idx_mirror;
404	  wr = tx_ring->write_idx_mirror;
405	
406	  if (rd_ptr != NULL)
407	    {
408	      *rd_ptr = rd;
409	    }
410	
411	  if (wr_ptr != NULL)
412	    {
413	      *wr_ptr = wr;
414	    }
415	
416	  return sf32lb58_bt_ring_data_len(rd, wr, tx_ring->buffer_size);
417	}
418	
419	static void sf32lb58_bt_trigger_tx(void)
420	{
421	  __DSB();
422	  ipc_hw_trigger_interrupt(&g_sf32lb58_bt_tx_hw);
423	}
424	
425	static int sf32lb58_bt_wait_tx_idle(struct circular_buf *tx_ring)
426	{
427	  uint32_t start_time = HAL_GetTick();
428	  uint32_t tick_count = 0;
429	  uint32_t rd_ptr = 0;
430	  uint32_t wr_ptr = 0;
431	
432	  while (sf32lb58_bt_tx_pending(tx_ring, &rd_ptr, &wr_ptr) > 0)
433	    {
434	      sf32lb58_bt_trigger_tx();
435	
436	      if (HAL_GetTick() != start_time)
437	        {
438	          tick_count++;
439	          start_time = HAL_GetTick();
440	        }
441	
442	      if (tick_count >= 100)
443	        {
444	          syslog(LOG_ERR,
445	                 "sf32lb58 bt tx busy: rd=%08lx wr=%08lx\n",
446	                 (unsigned long)rd_ptr,
447	                 (unsigned long)wr_ptr);
448	          return -ETIMEDOUT;
449	        }
450	
451	      usleep(1000);
452	    }
453	
454	  return OK;
455	}
456	
457	static size_t sf32lb58_bt_tx_chunk_len(const uint8_t *data,
458	                                       size_t len,
459	                                       size_t offset)
460	{
461	  size_t remaining = len - offset;
462	
463	  if (offset == 0 && remaining > 1)
464	    {
465	      return 1;
466	    }
467	
468	  return remaining;
469	}
470	
471	static void sf32lb58_bt_rx_worker(FAR void *arg)
472	{
473	  struct sf32lb58_bt_env_s *env = arg;
474	
475	  for (;;)
476	    {
477	      irqstate_t flags;
478	      int empty_retries = 0;
479	
480	      for (;;)
481	        {
482	          size_t size;
483	          size_t read_len;
484	          int ret;
485	          struct circular_buf *rx_ring;
486	          uint32_t wr_ptr;
487	
488	          flags = enter_critical_section();
489	
490	          if (!env->queue_open ||
491	              env->ipc_port == IPC_QUEUE_INVALID_HANDLE)
492	            {
493	              env->rx_work_pending = false;
494	              env->rx_worker_running = false;
495	              leave_critical_section(flags);
496	              return;
497	            }
498	
499	          leave_critical_section(flags);
500	
501	          up_invalidate_dcache((uintptr_t)SF32LB58_BT_RX_BUF_ADDR,
502	                               (uintptr_t)SF32LB58_BT_RX_BUF_ADDR +
503	                               SF32LB58_BT_RX_BUF_SIZE);
504	
505	          flags = enter_critical_section();
506	
507	          if (!env->queue_open ||
508	              env->ipc_port == IPC_QUEUE_INVALID_HANDLE)
509	            {
510	              env->rx_work_pending = false;
511	              env->rx_worker_running = false;
512	              leave_critical_section(flags);
513	              return;
514	            }
515	
516	          rx_ring = (struct circular_buf *)SF32LB58_BT_RX_BUF_ADDR;
517	          wr_ptr = rx_ring->write_idx_mirror;
518	          size = sf32lb58_bt_ring_data_len(env->rx_read_idx_mirror,
519	                                          wr_ptr,
520	                                          rx_ring->buffer_size);
521	          if (size == 0)
522	            {
523	              leave_critical_section(flags);
524	
525	              if (empty_retries++ < 20)
526	                {
527	                  usleep(1000);
528	                  continue;
529	                }
530	
531	              break;
532	            }
533	
534	          empty_retries = 0;
535	
536	          if (size > sizeof(env->data_buf))
537	            {
538	              size = sizeof(env->data_buf);
539	            }
540	
541	          read_len = sf32lb58_bt_ring_copy(env->data_buf, rx_ring,
542	                                           env->rx_read_idx_mirror, size);
543	          if (read_len == 0)
544	            {
545	              leave_critical_section(flags);
546	              break;
547	            }
548	
549	          env->rx_read_idx_mirror = sf32lb58_bt_ring_advance(
550	              env->rx_read_idx_mirror, read_len, rx_ring->buffer_size);
551	          rx_ring->read_idx_mirror = env->rx_read_idx_mirror;
552	          __DSB();
553	
554	          up_clean_dcache((uintptr_t)SF32LB58_BT_RX_BUF_ADDR,
555	                          (uintptr_t)SF32LB58_BT_RX_BUF_ADDR +
556	                          sizeof(*rx_ring));
557	
558	          env->rx_count++;
559	
560	          leave_critical_section(flags);
561	
562	          if (env->notify_host == NULL)
563	            {
564	              continue;
565	            }
566	
567	          ret = env->notify_host(env->data_buf, read_len);
568	          if (ret < 0)
569	            {
570	              syslog(LOG_ERR, "sf32lb58 bt rx callback: %d\n", ret);
571	            }
572	        }
573	
574	      flags = enter_critical_section();
575	      if (!env->rx_work_pending)
576	        {
577	          env->rx_worker_running = false;
578	          leave_critical_section(flags);
579	          break;
580	        }
581	
582	      env->rx_work_pending = false;
583	      leave_critical_section(flags);
584	    }
585	}
586	
587	static int32_t sf32lb58_bt_rx_ind(ipc_queue_handle_t handle, size_t size)
588	{
589	  struct sf32lb58_bt_env_s *env = &g_sf32lb58_bt_env;
590	  irqstate_t flags;
591	  bool queue_work;
592	
593	  if (handle != env->ipc_port)
594	    {
595	      return -EINVAL;
596	    }
597	
598	  if (!env->queue_open)
599	    {
600	      return OK;
601	    }
602	
603	  flags = enter_critical_section();
604	  env->rx_work_pending = true;
605	  queue_work = !env->rx_worker_running && work_available(&env->rx_work);
606	  if (queue_work)
607	    {
608	      env->rx_worker_running = true;
609	    }
610	  leave_critical_section(flags);
611	
612	  if (queue_work)
613	    {
614	      int ret;
615	
616	      ret = work_queue(HPWORK, &env->rx_work, sf32lb58_bt_rx_worker,
617	                       env, 0);
618	      if (ret < 0)
619	        {
620	          flags = enter_critical_section();
621	          env->rx_worker_running = false;
622	          leave_critical_section(flags);
623	
624	          syslog(LOG_ERR, "sf32lb58 bt queue rx work failed: %d\n", ret);
625	          return ret;
626	        }
627	    }
628	
629	  return OK;
630	}
