632	static int sf32lb58_bt_mailbox_init(void)
633	{
634	  struct sf32lb58_bt_env_s *env = &g_sf32lb58_bt_env;
635	  ipc_queue_cfg_t q_cfg;
636	
637	  memset(&q_cfg, 0, sizeof(q_cfg));
638	  q_cfg.qid = SF32LB58_BT_QID;
639	  q_cfg.tx_buf_size = SF32LB58_BT_TX_BUF_SIZE;
640	  q_cfg.tx_buf_addr = SF32LB58_BT_TX_BUF_ADDR;
641	  q_cfg.tx_buf_addr_alias = SF32LB58_BT_TX_BUF_ALIAS;
642	  q_cfg.rx_buf_addr = SF32LB58_BT_RX_BUF_ADDR;
643	  q_cfg.rx_ind = sf32lb58_bt_rx_ind;
644	
645	  env->ipc_port = ipc_queue_init(&q_cfg);
646	  if (env->ipc_port == IPC_QUEUE_INVALID_HANDLE)
647	    {
648	      return -ENODEV;
649	    }
650	
651	  return OK;
652	}
