678	int sf32lb58_bt_controller_deinit(void)
679	{
680	  int ret;
681	
682	  if (g_sf32lb58_bt_status == SF32LB58_BT_STATUS_ENABLED)
683	    {
684	      ret = sf32lb58_bt_controller_disable();
685	      if (ret < 0)
686	        {
687	          return ret;
688	        }
689	    }
690	
691	  if (g_sf32lb58_bt_status != SF32LB58_BT_STATUS_INITED)
692	    {
693	      return -EPERM;
694	    }
695	
696	  g_sf32lb58_bt_env.queue_open = false;
697	  g_sf32lb58_bt_env.rx_work_pending = false;
698	  g_sf32lb58_bt_env.rx_worker_running = false;
699	  if (!work_available(&g_sf32lb58_bt_env.rx_work))
700	    {
701	      ret = work_cancel_sync(HPWORK, &g_sf32lb58_bt_env.rx_work);
702	      if (ret < 0 && ret != -ENOENT)
703	        {
704	          return ret;
705	        }
706	    }
707	
708	  ret = ipc_queue_deinit(g_sf32lb58_bt_env.ipc_port);
709	  if (ret < 0)
710	    {
711	      return ret;
712	    }
713	
714	  memset(&g_sf32lb58_bt_env, 0, sizeof(g_sf32lb58_bt_env));
715	  g_sf32lb58_bt_env.ipc_port = IPC_QUEUE_INVALID_HANDLE;
716	  g_sf32lb58_bt_status = SF32LB58_BT_STATUS_IDLE;
