736	int sf32lb58_bt_controller_enable(void)
737	{
738	  int ret;
739	
740	  if (g_sf32lb58_bt_status == SF32LB58_BT_STATUS_ENABLED)
741	    {
742	      return OK;
743	    }
744	
745	  if (g_sf32lb58_bt_status != SF32LB58_BT_STATUS_INITED)
746	    {
747	      return -EPERM;
748	    }
749	
750	  syslog(LOG_INFO, "sf32lb58 bt: preparing NVDS at 0x%08x size %d\n",
751	         (unsigned int)SF32LB58_BT_NVDS_BUF_START,
752	         (int)SF32LB58_BT_NVDS_BUF_SIZE);
753	  sf32lb58_bt_prepare_stack_nvds();
754	  HAL_LCPU_ASSERT_INFO_clear();
755	
756	  /* Wake the LCPU first so the LPSYS bus bridge is powered.
757	   * This must happen BEFORE lcpu_power_on() because the IPC mailbox
758	   * CxIER register is on the LPSYS APB bus and only writable when
759	   * the bus bridge is active.  lcpu_power_on() will reset+halt the
760	   * LCPU and reconfigure it, so this early wake is just for the bus
761	   * bridge power domain.
762	   */
763	
764	  HAL_HPAON_WakeCore(CORE_ID_LCPU);
765	  g_sf32lb58_bt_env.wake_held = true;
766	
767	  syslog(LOG_INFO, "sf32lb58 bt: powering on LCPU\n");
768	  ret = lcpu_power_on();
769	  if (ret != 0)
770	    {
771	      syslog(LOG_ERR, "sf32lb58 bt: lcpu_power_on failed: %d\n", ret);
772	      return -EIO;
773	    }
774	
775	  syslog(LOG_INFO, "sf32lb58 bt: LCPU powered on, opening IPC\n");
776	
777	  /* lcpu_power_on() keeps the bus bridge active (no cancel inside).
778	   * Open the IPC queue while the bridge is powered, then cancel.
779	   */
780	
781	  g_sf32lb58_bt_env.wake_held = true;
782	
783	  syslog(LOG_INFO, "sf32lb58 bt: calling ipc_queue_open\n");
784	  ret = ipc_queue_open(g_sf32lb58_bt_env.ipc_port);
785	  syslog(LOG_INFO, "sf32lb58 bt: ipc_queue_open returned %d\n", ret);
786	
787	  /* Check if NVIC interrupt for mailbox is enabled */
788	  {
789	    uint32_t iser0 = NVIC->ISER[0];
790	    uint32_t iser1 = NVIC->ISER[1];
791	    syslog(LOG_INFO, "sf32lb58 bt: NVIC ISER0=%08lx ISER1=%08lx\n",
792	           (unsigned long)iser0, (unsigned long)iser1);
793	  }
794	  if (ret < 0)
795	    {
796	      HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
797	      g_sf32lb58_bt_env.wake_held = false;
798	      return ret;
799	    }
800	
801	  syslog(LOG_INFO, "sf32lb58 bt: flushing TX ring, then waiting RX ring\n");
802	  up_clean_dcache((uintptr_t)SF32LB58_BT_TX_BUF_ADDR,
803	                  (uintptr_t)SF32LB58_BT_TX_BUF_ADDR +
804	                  SF32LB58_BT_TX_BUF_SIZE);
805	  __DSB();
806	
807	  {
808	    struct circular_buf *rx_ring =
809	        (struct circular_buf *)SF32LB58_BT_RX_BUF_ADDR;
810	
811	    ret = sf32lb58_bt_wait_rx_ring_ready();
812	    if (ret < 0)
813	      {
814	        syslog(LOG_ERR, "sf32lb58 rx ring not ready: %d\n", ret);
815	        ipc_queue_close(g_sf32lb58_bt_env.ipc_port);
816	        HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
817	        g_sf32lb58_bt_env.wake_held = false;
818	        return ret;
819	      }
820	
821	    rx_ring->read_idx_mirror = rx_ring->write_idx_mirror;
822	    g_sf32lb58_bt_env.rx_read_idx_mirror = rx_ring->write_idx_mirror;
823	
824	    up_clean_dcache((uintptr_t)SF32LB58_BT_RX_BUF_ADDR,
825	                    (uintptr_t)SF32LB58_BT_RX_BUF_ADDR +
826	                    sizeof(*rx_ring));
827	    __DSB();
828	  }
829	
830	  g_sf32lb58_bt_env.queue_open = true;
831	  g_sf32lb58_bt_status = SF32LB58_BT_STATUS_ENABLED;
832	
833	  return OK;
834	}
835	
836	int sf32lb58_bt_controller_disable(void)
837	{
838	  int ret = OK;
839	  int tmpret;
840	  bool queue_open;
841	
842	  if (g_sf32lb58_bt_status != SF32LB58_BT_STATUS_ENABLED)
843	    {
844	      return -EPERM;
845	    }
846	
847	  queue_open = g_sf32lb58_bt_env.queue_open;
848	  g_sf32lb58_bt_env.queue_open = false;
849	  g_sf32lb58_bt_env.rx_work_pending = false;
850	  g_sf32lb58_bt_env.rx_worker_running = false;
851	  if (!work_available(&g_sf32lb58_bt_env.rx_work))
852	    {
853	      tmpret = work_cancel_sync(HPWORK, &g_sf32lb58_bt_env.rx_work);
854	      if (tmpret < 0 && tmpret != -ENOENT && ret == OK)
855	        {
856	          ret = tmpret;
857	        }
858	    }
859	
860	  if (queue_open)
861	    {
862	      tmpret = ipc_queue_close(g_sf32lb58_bt_env.ipc_port);
863	      if (tmpret < 0 && ret == OK)
864	        {
865	          ret = tmpret;
866	        }
867	    }
868	
869	  if (g_sf32lb58_bt_env.wake_held)
870	    {
871	      HAL_HPAON_CANCEL_LP_ACTIVE_REQUEST();
872	      g_sf32lb58_bt_env.wake_held = false;
873	    }
874	
875	  tmpret = lcpu_power_off();
876	  if (tmpret != 0 && ret == OK)
877	    {
878	      ret = -EIO;
879	    }
880	
881	  g_sf32lb58_bt_env.notify_host = NULL;
882	  g_sf32lb58_bt_status = SF32LB58_BT_STATUS_INITED;
883	  return ret;
884	}
885	
886	int sf32lb58_host_send_packet(const uint8_t *data, uint16_t len)
887	{
888	  struct circular_buf *tx_ring =
889	      (struct circular_buf *)SF32LB58_BT_TX_BUF_ADDR;
890	  uint32_t start_time;
891	  uint32_t tick_count;
892	  size_t written;
893	  size_t remaining;
894	  size_t offset;
895	  size_t chunk;
896	  size_t chunks;
897	  uint32_t wr_ptr;
898	  int ret;
899	
900	  if (data == NULL || len == 0)
901	    {
902	      return -EINVAL;
903	    }
904	
905	  if (g_sf32lb58_bt_status != SF32LB58_BT_STATUS_ENABLED ||
906	      !g_sf32lb58_bt_env.queue_open)
907	    {
908	      syslog(LOG_ERR, "sf32lb58 send: not ready status=%d open=%d\n",
909	             g_sf32lb58_bt_status, g_sf32lb58_bt_env.queue_open);
910	      return -ENODEV;
911	    }
912	
913	  syslog(LOG_INFO, "sf32lb58 send: len=%d type=%02x\n",
914	         len, data[0]);
915	
916	  offset = 0;
917	  remaining = len;
918	  start_time = HAL_GetTick();
919	  tick_count = 0;
920	  chunks = 0;
921	  wr_ptr = 0;
922	
923	  ret = sf32lb58_bt_wait_tx_idle(tx_ring);
924	  if (ret < 0)
925	    {
926	      return ret;
927	    }
928	
929	  while (remaining > 0)
930	    {
931	      irqstate_t flags;
932	
933	      chunk = sf32lb58_bt_tx_chunk_len(data, len, offset);
934	
935	      up_invalidate_dcache((uintptr_t)SF32LB58_BT_TX_BUF_ADDR,
936	                           (uintptr_t)SF32LB58_BT_TX_BUF_ADDR +
937	                           sizeof(*tx_ring));
938	
939	      flags = enter_critical_section();
940	      written = sf32lb58_bt_ring_write(tx_ring, data + offset, chunk);
941	      leave_critical_section(flags);
942	
943	      if (written == 0)
944	        {
945	          if (HAL_GetTick() != start_time)
946	            {
947	              tick_count++;
948	              start_time = HAL_GetTick();
949	            }
950	
951	          if (tick_count >= 10)
952	            {
953	              syslog(LOG_ERR,
954	                     "sf32lb58 bt tx timeout: remaining=%lu\n",
955	                     (unsigned long)remaining);
956	              return -ETIMEDOUT;
957	            }
958	
959	          continue;
960	        }
961	
962	      offset += written;
963	      remaining -= written;
964	
965	      __DSB();
966	      wr_ptr = tx_ring->write_idx_mirror;
967	      sf32lb58_bt_trigger_tx();
968	      chunks++;
969	    }
970	
971	  if (data[0] == SF32LB58_BT_H4_CMD)
972	    {
973	      up_invalidate_dcache((uintptr_t)SF32LB58_BT_TX_BUF_ADDR,
974	                           (uintptr_t)SF32LB58_BT_TX_BUF_ADDR +
975	                           sizeof(*tx_ring));
976	      syslog(LOG_INFO,
977	             "sf32lb58 send: after trigger rd=%08lx wr=%08lx\n",
978	             (unsigned long)tx_ring->read_idx_mirror,
979	             (unsigned long)tx_ring->write_idx_mirror);
980	
981	      ret = sf32lb58_bt_wait_tx_idle(tx_ring);
982	      if (ret < 0)
983	        {
984	          syslog(LOG_ERR, "sf32lb58 send: wait_tx_idle failed: %d\n", ret);
985	          return ret;
986	        }
987	    }
988	
989	  return OK;
990	}
