42	 *
43	 *
44	 * @param[out] hw_q_handle hw queue handle
45	 * @param[in] qid queue id, numbering across all queues in all channels
46	 * @param[in] user_data user data
47	 * @retval status, 0: success, otherwise: fail
48	 *
49	 */
50	int32_t ipc_hw_enable_interrupt(ipc_hw_q_handle_t *hw_q_handle, uint8_t qid, uint32_t user_data)
51	{
52	    uint8_t ch_id;
53	    int32_t result = -1;
54	    uint8_t q_idx;
55	    ipc_hw_ch_t *ch;
56	    ipc_ch_cfg_t *ch_cfg;
57	
58	    SF_ASSERT(hw_q_handle);
59	
60	    ch_id = qid / IPC_HW_QUEUE_NUM;
61	    if (ch_id >= IPC_HW_CH_NUM)
62	    {
63	        return result;
64	    }
65	
66	    ch = &ipc_hw_obj.ch[ch_id];
67	    ch_cfg = &ch->cfg;
68	    q_idx = qid - ch_id * IPC_HW_QUEUE_NUM;
69	    ch->data.user_data[q_idx] = user_data;
70	    ch->data.act_bitmap |= (1UL << q_idx);
71	    hw_q_handle->ch_id = ch_id;
72	    hw_q_handle->q_idx = q_idx;
73	
74	#ifdef RISCV
75	    ECLIC_Register_IRQ(ch_cfg->rx.irqn, ECLIC_NON_VECTOR_INTERRUPT, ECLIC_LEVEL_TRIGGER, 3, 0, NULL);
76	#else
77	
78	    /* receiver enable NVIC IRQ */
79	    os_interrupt_start(ch_cfg->rx.irqn, 3, 0);
80	#endif
81	    /* sender unmask interrupt */
82	    __HAL_MAILBOX_UNMASK_CHANNEL_IT(&ch_cfg->tx.handle, q_idx);
83	
84	    result = 0;
85	
86	    return result;
87	}
