31	#define IPC_LOGICAL_QUEUE_NUM    (4)
32	#define IPC_INVALID_QUEUE_ID     (UINT8_MAX)
33	#define IPC_QUEUE_HANDLE_OFFSET  (10)
34	#define IPC_QUEUE_HANDLE_2_OFFSET(handle)  ((handle) - IPC_QUEUE_HANDLE_OFFSET)
35	#define IPC_QUEUE_OFFSET_2_HANDLE(offset)  ((offset) + IPC_QUEUE_HANDLE_OFFSET)
36	
