46	static bool is_valid_handle(ipc_queue_handle_t handle)
47	{
48	    bool valid = false;
49	    int32_t offset;
50	
51	    if (!ipc_ctx.init)
52	    {
53	        return valid;
54	    }
55	
56	    if ((handle < IPC_QUEUE_HANDLE_OFFSET)
57	            || ((handle - IPC_QUEUE_HANDLE_OFFSET) >= IPC_LOGICAL_QUEUE_NUM))
58	    {
59	        return valid;
60	    }
61	
62	    offset = IPC_QUEUE_HANDLE_2_OFFSET(handle);
63	    if (IPC_INVALID_QUEUE_ID == ipc_ctx.queues[offset].cfg.qid)
64	    {
65	        return valid;
66	    }
67	
68	    valid = true;
69	
70	    return valid;
71	}
