73	__ROM_USED ipc_queue_handle_t ipc_queue_init(ipc_queue_cfg_t *q_cfg)
74	{
75	    uint32_t i;
76	    ipc_queue_handle_t handle = IPC_QUEUE_INVALID_HANDLE;
77	    int32_t offset;
78	    ipc_queue_t *ipc_queue;
79	    uint32_t mask;
80	
81	    if (NULL == q_cfg)
82	    {
83	        return handle;
84	    }
85	
86	    mask = os_interrupt_disable();
87	
88	    /* initialize ipc queues */
89	    if (!ipc_ctx.init)
90	    {
91	        for (i = 0; i < IPC_LOGICAL_QUEUE_NUM; i++)
92	        {
93	            ipc_ctx.queues[i].cfg.qid = IPC_INVALID_QUEUE_ID;
94	            ipc_ctx.queues[i].active = false;
95	        }
96	        ipc_ctx.init = true;
97	    }
98	
99	    ipc_queue = &ipc_ctx.queues[0];
100	    offset = -1;
101	    for (i = 0; i < IPC_LOGICAL_QUEUE_NUM; i++)
102	    {
103	        if (q_cfg->qid == ipc_queue->cfg.qid)
104	        {
105	            /* qid already present */
106	            handle = IPC_QUEUE_INVALID_HANDLE;
107	            break;
108	        }
109	        if ((IPC_QUEUE_INVALID_HANDLE == handle)
110	                && (IPC_INVALID_QUEUE_ID == ipc_queue->cfg.qid))
111	        {
112	            /* first vacant found */
113	            offset = i;
114	            handle = IPC_QUEUE_OFFSET_2_HANDLE(offset);
115	        }
116	        ipc_queue++;
117	    }
118	
119	    if ((i >= IPC_LOGICAL_QUEUE_NUM) && (offset >= 0))
120	    {
121	        /* new qid and vacant found */
122	        memcpy(&ipc_ctx.queues[offset].cfg, q_cfg, sizeof(*q_cfg));
123	        ipc_ctx.queues[offset].data_len = 0;
124	        ipc_ctx.queues[offset].active = false;
125	    }
126	
127	    os_interrupt_enable(mask);
128	
129	    return handle;
130	}
