132	__ROM_USED int32_t ipc_queue_get_user_data(ipc_queue_handle_t handle, uint32_t *user_data)
133	{
134	    int32_t result = -1;
135	    ipc_queue_t *queue;
136	    uint32_t mask;
137	    int32_t offset;
138	
139	    if (!user_data)
140	    {
141	        return result;
142	    }
143	
