441	__ROM_USED size_t ipc_queue_write(ipc_queue_handle_t handle, const void *buffer, size_t size, uint32_t timeout)
442	{
443	    size_t data_len;
444	    uint32_t start_time;
445	    uint32_t cnt;
446	    uint32_t total_len;
447	    ipc_queue_t *queue;
448	    int32_t offset;
449	
450	    if (!is_valid_handle(handle))
451	    {
452	        return 0;
453	    }
454	
455	    offset = IPC_QUEUE_HANDLE_2_OFFSET(handle);
456	    queue = &ipc_ctx.queues[offset];
457	    if (!queue->active)
458	    {
459	        return 0;
460	    }
461	
462	    if (NULL == buffer)
463	    {
464	        /* just trigger interrupt */
465	        ipc_hw_trigger_interrupt(&queue->hw_q_handle);
466	        return 0;
467	    }
468	
469	    if (!queue->tx_ring_buffer)
470	    {
471	        return 0;
472	    }
473	
474	    cnt = 0;
475	    start_time = HAL_GetTick();
476	    total_len = size;
477	    while (total_len > 0)
478	    {
479	        data_len = circular_buf_put(queue->tx_ring_buffer, buffer, total_len);
480	        SF_ASSERT(data_len <= total_len);
481	        total_len -= data_len;
482	        buffer = (uint8_t *)buffer + data_len;
483	
484	        if (data_len > 0)
485	        {
486	            /* trigger mailbox if new data has been written */
487	            ipc_hw_trigger_interrupt(&queue->hw_q_handle);
488	        }
489	        if (HAL_GetTick() != start_time)
490	        {
491	            cnt++;
492	            start_time = HAL_GetTick();
493	        }
494	        if (cnt >= timeout)
495	        {
496	            break;
497	        }
498	    }
499	
500	    return (size - total_len);
501	}
