503	__ROM_USED bool ipc_queue_check_idle(void)
504	{
505	    bool is_idle = true;
506	    uint32_t i;
507	    ipc_queue_t *q;
508	    uint32_t mask;
509	
510	    if (!ipc_ctx.init)
511	    {
512	        goto __END;
513	    }
514	
515	    mask = os_interrupt_disable();
516	    q = &ipc_ctx.queues[0];
517	    for (i = 0; i < IPC_LOGICAL_QUEUE_NUM; i++)
518	    {
519	        /* interrupt has not been handled by receiver */
520	        if (q->active && (0 != ipc_hw_check_interrupt(&q->hw_q_handle)))
521	        {
522	            is_idle = false;
523	            break;
524	        }
525	        if (q->active && q->tx_ring_buffer
526	                && circular_buf_data_len(q->tx_ring_buffer) > 0)
527	        {
528	            is_idle = false;
529	            break;
530	        }
531	        q++;
532	    }
533	    os_interrupt_enable(mask);
534	
535	__END:
536	
537	    return is_idle;
538	}
