19	static inline enum circular_buf_state circular_buf_status(struct circular_buf *cb, uint32_t rd_ptr, uint32_t wr_ptr)
20	{
21	    uint32_t rd_idx;
22	    uint32_t wr_idx;
23	    uint32_t rd_mirror;
24	    uint32_t wr_mirror;
25	
26	    rd_idx = CB_GET_PTR_IDX(rd_ptr);
27	    rd_mirror = CB_GET_PTR_MIRROR(rd_ptr);
28	    wr_idx = CB_GET_PTR_IDX(wr_ptr);
29	    wr_mirror = CB_GET_PTR_MIRROR(wr_ptr);
30	
31	    if (rd_idx == wr_idx)
32	    {
33	        if (rd_mirror == wr_mirror)
34	        {
35	            return CIRCULAR_BUF_EMPTY;
36	        }
37	        else
38	        {
39	            return CIRCULAR_BUF_FULL;
40	        }
41	    }
42	    return CIRCULAR_BUF_HALFFULL;
43	}
