89	/**
90	 * put a block of data into ring buffer
91	 */
92	__ROM_USED size_t circular_buf_put(struct circular_buf *cb,
93	                                   const uint8_t     *ptr,
94	                                   uint16_t           length)
95	{
96	    uint16_t size;
97	    uint32_t wr_mirror;
98	    uint32_t wr_idx;
99	
100	    SF_ASSERT(cb != NULL);
101	
102	    /* whether has enough space */
103	    size = circular_buf_space_len(cb);
104	
105	    /* no space */
106	    if (size == 0)
107	    {
108	        return 0;
109	    }
110	
111	    /* drop some data */
112	    if (size < length)
113	    {
114	        length = size;
115	    }
116	
117	    wr_idx = CB_GET_PTR_IDX(cb->write_idx_mirror);
118	    wr_mirror = CB_GET_PTR_MIRROR(cb->write_idx_mirror);
119	    if ((cb->buffer_size - wr_idx) > length)
120	    {
121	        /* read_index - write_index = empty space */
122	        memcpy(&cb->wr_buffer_ptr[wr_idx], ptr, length);
123	        /* this should not cause overflow because there is enough space for
124	         * length of data in current mirror */
125	        wr_idx += length;
126	        cb->write_idx_mirror = CB_MAKE_PTR_IDX_MIRROR(wr_idx, wr_mirror);
127	        return length;
128	    }
129	
130	    memcpy(&cb->wr_buffer_ptr[wr_idx],
131	           &ptr[0],
132	           cb->buffer_size - wr_idx);
133	    memcpy(&cb->wr_buffer_ptr[0],
134	           &ptr[cb->buffer_size - wr_idx],
135	           length - (cb->buffer_size - wr_idx));
136	
137	    /* we are going into the other side of the mirror */
138	    wr_mirror = ~wr_mirror;
139	    wr_idx = length - (cb->buffer_size - wr_idx);
140	    cb->write_idx_mirror = CB_MAKE_PTR_IDX_MIRROR(wr_idx, wr_mirror);
141	
142	    return length;
143	}
