175	        /* this should not cause overflow because there is enough space for
176	         * length of data in current mirror */
177	        wr_idx += length;
178	        cb->write_idx_mirror = CB_MAKE_PTR_IDX_MIRROR(wr_idx, wr_mirror);
179	
180	        if (length > space_length)
181	        {
182	            rd_mirror = CB_GET_PTR_MIRROR(cb->read_idx_mirror);
183	            cb->read_idx_mirror = CB_MAKE_PTR_IDX_MIRROR(wr_idx, rd_mirror);
184	        }
185	
186	        return length;
187	    }
188	
189	    memcpy(&cb->wr_buffer_ptr[wr_idx],
190	           &ptr[0],
191	           cb->buffer_size - wr_idx);
192	    memcpy(&cb->wr_buffer_ptr[0],
193	           &ptr[cb->buffer_size - wr_idx],
194	           length - (cb->buffer_size - wr_idx));
195	
196	    /* we are going into the other side of the mirror */
197	    wr_mirror = ~wr_mirror;
198	    wr_idx = length - (cb->buffer_size - wr_idx);
199	    cb->write_idx_mirror = CB_MAKE_PTR_IDX_MIRROR(wr_idx, wr_mirror);
200	
201	    if (length > space_length)
202	    {
203	        rd_mirror = CB_GET_PTR_MIRROR(cb->read_idx_mirror);
204	        rd_mirror = ~rd_mirror;
205	        cb->read_idx_mirror = CB_MAKE_PTR_IDX_MIRROR(wr_idx, rd_mirror);
206	    }
207	
208	    return length;
209	}
