342	/**
343	 * put a character into ring buffer
344	 */
345	__ROM_USED size_t circular_buf_putchar(struct circular_buf *cb, const uint8_t ch)
346	{
347	    uint32_t wr_mirror;
348	    uint32_t wr_idx;
349	
350	    SF_ASSERT(cb != NULL);
351	
352	    /* whether has enough space */
353	    if (!circular_buf_space_len(cb))
354	        return 0;
355	
356	    wr_idx = CB_GET_PTR_IDX(cb->write_idx_mirror);
357	    wr_mirror = CB_GET_PTR_MIRROR(cb->write_idx_mirror);
358	    cb->wr_buffer_ptr[wr_idx] = ch;
359	
360	    /* flip mirror */
361	    if ((int16_t)wr_idx == cb->buffer_size - 1)
362	    {
363	        wr_mirror = ~wr_mirror;
364	        wr_idx = 0;
365	    }
366	    else
367	    {
368	        wr_idx++;
369	    }
370	    cb->write_idx_mirror = CB_MAKE_PTR_IDX_MIRROR(wr_idx, wr_mirror);
371	
372	    return 1;
373	}
