380	__ROM_USED size_t circular_buf_putchar_force(struct circular_buf *cb, const uint8_t ch)
381	{
382	    enum circular_buf_state old_state;
383	    uint32_t wr_mirror;
384	    uint32_t wr_idx;
385	    uint32_t rd_mirror;
386	
387	    SF_ASSERT(cb != NULL);
388	
389	    old_state = circular_buf_status(cb, cb->read_idx_mirror, cb->write_idx_mirror);
390	
391	    wr_idx = CB_GET_PTR_IDX(cb->write_idx_mirror);
392	    wr_mirror = CB_GET_PTR_MIRROR(cb->write_idx_mirror);
393	    cb->wr_buffer_ptr[wr_idx] = ch;
394	
395	    /* flip mirror */
396	    if ((int16_t)wr_idx == cb->buffer_size - 1)
397	    {
398	        wr_mirror = ~wr_mirror;
399	        wr_idx = 0;
400	        if (old_state == CIRCULAR_BUF_FULL)
401	        {
402	            rd_mirror = CB_GET_PTR_MIRROR(cb->read_idx_mirror);
403	            rd_mirror = ~rd_mirror;
404	            cb->read_idx_mirror = CB_MAKE_PTR_IDX_MIRROR(wr_idx, rd_mirror);
405	        }
406	    }
407	    else
408	    {
409	        wr_idx++;
410	        if (old_state == CIRCULAR_BUF_FULL)
411	        {
412	            rd_mirror = CB_GET_PTR_MIRROR(cb->read_idx_mirror);
413	            cb->read_idx_mirror = CB_MAKE_PTR_IDX_MIRROR(wr_idx, rd_mirror);
414	        }
415	    }
416	
417	    return 1;
418	}
