424	{
425	    uint32_t rd_mirror;
426	    uint32_t rd_idx;
427	
428	    SF_ASSERT(cb != NULL);
429	
430	    /* circular_buf is empty */
431	    if (!circular_buf_data_len(cb))
432	        return 0;
433	
434	    rd_idx = CB_GET_PTR_IDX(cb->read_idx_mirror);
435	    rd_mirror = CB_GET_PTR_MIRROR(cb->read_idx_mirror);
436	
437	    /* put character */
438	    *ch = cb->rd_buffer_ptr[rd_idx];
439	
440	    if ((int16_t)rd_idx == cb->buffer_size - 1)
441	    {
442	        rd_mirror = ~rd_mirror;
443	        rd_idx = 0;
444	    }
445	    else
446	    {
447	        rd_idx++;
448	    }
449	    cb->read_idx_mirror = CB_MAKE_PTR_IDX_MIRROR(rd_idx, rd_mirror);
450	
451	    return 1;
