454	/**
455	 * get the size of data in cb
456	 */
457	__ROM_USED size_t circular_buf_data_len(struct circular_buf *cb)
458	{
459	    uint32_t rd_idx;
460	    uint32_t wr_idx;
461	    uint32_t rd_ptr;
462	    uint32_t wr_ptr;
463	
464	    rd_ptr = cb->read_idx_mirror;
465	    wr_ptr = cb->write_idx_mirror;
466	    switch (circular_buf_status(cb, rd_ptr, wr_ptr))
467	    {
468	    case CIRCULAR_BUF_EMPTY:
469	        return 0;
470	    case CIRCULAR_BUF_FULL:
471	        return cb->buffer_size;
472	    case CIRCULAR_BUF_HALFFULL:
473	    default:
474	        rd_idx = CB_GET_PTR_IDX(rd_ptr);
475	        wr_idx = CB_GET_PTR_IDX(wr_ptr);
476	        if (wr_idx > rd_idx)
477	            return wr_idx - rd_idx;
478	        else
479	            return cb->buffer_size - (rd_idx - wr_idx);
480	    };
481	}
