53	void lcpu_rom_config_default(void)
54	{
55	  uint8_t is_enable_lxt;
56	
57	  syslog(LOG_INFO, "sf32lb58 lcpu_boot: lcpu_rom_config_default\n");
58	  uint8_t is_lcpu_rccal = 0;
59	  uint32_t wdt_staus = 0xFF;
60	  uint32_t wdt_time = 10;
61	  uint16_t wdt_clk = 32768;
62	
63	  if (HAL_LXT_DISABLED())
64	    {
65	      is_lcpu_rccal = 1;
66	    }
67	
68	  is_enable_lxt = 1 - is_lcpu_rccal;
69	  HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_XTAL_ENABLED, &is_enable_lxt, 1);
70	  HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_WDT_STATUS, &wdt_staus, 4);
71	  HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_WDT_TIME, &wdt_time, 4);
72	  HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_WDT_CLK_FEQ, &wdt_clk, 2);
73	  HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_BT_RC_CAL_IN_L, &is_lcpu_rccal, 1);
74	
75	  {
76	    uint32_t tx_queue = HCPU2LCPU_MB_CH1_BUF_START_ADDR;
77	    hal_lcpu_bluetooth_rom_config_t config = {0};
78	
79	    config.bit_valid |= 1 << 10 | 1 << 6;
80	    config.is_fpga = 0;

80	    config.is_fpga = 0;
81	    config.default_xtal_enabled = is_enable_lxt;
82	    HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_HCPU_TX_QUEUE, &tx_queue, 4);
83	    HAL_LCPU_CONFIG_set(HAL_LCPU_CONFIG_BT_CONFIG, &config, sizeof(config));
84	  }
85	}
