92	static void lcpu_ble_patch_install(void)
93	{
94	  memset((void *)0x204F0000, 0, 0x2000);
95	
96	  /* Install the LCPU ROM patch.  The patch file is selected at build
97	   * time by silicon revision: lcpu_patch.c for A1, lcpu_patch_a2.c for
98	   * A2 (see CMakeLists.txt).  Both define the same symbol.
99	   */
100	  lcpu_patch_install();
101	
102	  /* Flush the patch bin/record and the BT EM buffer written above.
103	   * The LCPU ROM reads these directly from the bus (no cache), so any
104	   * lines still sitting in the HCPU D-cache would be invisible to it
105	   * and the patch would silently not install.
106	   */
107	  sf32lb58_lcpu_boot_clean_range((uint32_t)LCPU_PATCH_BUF_START_ADDR,
108	                                 LCPU_PATCH_BUF_SIZE);
109	  sf32lb58_lcpu_boot_clean_range((uint32_t)LCPU_PATCH_RECORD_ADDR,
110	                                 LCPU_PATCH_RECORD_SIZE);
111	  sf32lb58_lcpu_boot_clean_range(0x204F0000, 0x2000);
112	
113	  syslog(LOG_INFO,
114	         "sf32lb58 lcpu_boot: chip rev=%u patch CER=0x%lx record=0x%lx\n",
115	         (unsigned int)__HAL_SYSCFG_GET_REVID(),
116	         (unsigned long)hwp_patch->CER,
117	         (unsigned long)*(volatile uint32_t *)LCPU_PATCH_RECORD_ADDR);
118	
119	  if (g_lcpu_rf_cal_disable == 0)
120	    {
121	      extern void bt_rf_cal(void);
122	      bt_rf_cal();
123	    }
124	
125	  adc_resume();
126	}
